@'
import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
const installed=path.join(process.env.APPDATA,'npm/node_modules/@vxu-labs/dip');
for(const folder of ['src','bin','public','skills/dip'])for(const name of fs.readdirSync(folder)){const file=path.join(folder,name);if(!fs.statSync(file).isFile())continue;const other=path.join(installed,folder,name);if(createHash('sha256').update(fs.readFileSync(file)).digest('hex')!==createHash('sha256').update(fs.readFileSync(other)).digest('hex'))throw Error('Installed mismatch '+file);}
console.log('Installed runtime and skill match release source.');
'@ | node --input-type=module
git status --short --untracked-files=no
git rev-list --left-right --count HEAD...origin/main
